	var writes := RegEx.create_from_string("fire\\.[A-Za-z_]+\\s*=[^=]").search_all(src)
	var asks: Array = RegEx.create_from_string("fire\\.call\\(\"([a-z_]+)\"").search_all(src).map(
		func(m: RegExMatch) -> String: return m.get_string(1))
